Object.entries(purposeContactTranslations).forEach(([code, copy]) => {
  Object.assign(translations[code], copy);
});

const storageKey = "nokegames.language";
const supportedCodes = new Set(languages.map(({ code }) => code));

export function applyLanguage(code, { persist = true } = {}) {
  const language = supportedCodes.has(code) ? code : "es";
  const copy = translations[language];
  const direction = languages.find(({ code: itemCode }) => itemCode === language)?.dir ?? "ltr";

  document.documentElement.lang = language;
  document.documentElement.dir = direction;
  document.title = copy.metaTitle;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (copy[key]) element.textContent = copy[key];
  });

  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    const key = element.dataset.i18nAria;
    if (copy[key]) element.setAttribute("aria-label", copy[key]);
  });

  const dateFormatter = new Intl.DateTimeFormat(language, {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
  document.querySelectorAll("time[data-i18n-date]").forEach((element) => {
    const value = element.getAttribute("datetime");
    if (value) element.textContent = dateFormatter.format(new Date(`${value}T00:00:00Z`));
  });

  const description = document.querySelector('meta[name="description"]');
  const ogTitle = document.querySelector('meta[property="og:title"]');
  const ogDescription = document.querySelector('meta[property="og:description"]');
  const twitterTitle = document.querySelector('meta[name="twitter:title"]');
  const twitterDescription = document.querySelector('meta[name="twitter:description"]');
  if (description) description.content = copy.metaDescription;
  if (ogTitle) ogTitle.content = copy.metaTitle;
  if (ogDescription) ogDescription.content = copy.metaDescription;
  if (twitterTitle) twitterTitle.content = copy.metaTitle;
  if (twitterDescription) twitterDescription.content = copy.metaDescription;

  const selector = document.querySelector("#language-select");
  if (selector) selector.value = language;
  if (persist) window.localStorage.setItem(storageKey, language);
}

if (typeof document !== "undefined") {
  const saved = window.localStorage.getItem(storageKey);
  const browserLanguage = window.navigator.language?.split("-")[0];
  const initialLanguage = supportedCodes.has(saved)
    ? saved
    : supportedCodes.has(browserLanguage)
      ? browserLanguage
      : "es";

  applyLanguage(initialLanguage, { persist: false });
  document.querySelector("#language-select")?.addEventListener("change", (event) => {
    applyLanguage(event.target.value);
  });

  const contactSuccess = document.querySelector("#contact-success");
  if (new URLSearchParams(window.location.search).get("contacto") === "enviado" && contactSuccess) {
    contactSuccess.hidden = false;
    contactSuccess.focus({ preventScroll: true });
  }
}
